package com.pratik.imagetap;
import android.content.*;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.zip.*;
/** Portable whole-app backup. Runtime state and Android permissions are never transferred. */
final class GlobalArchive {
 static final long LIMIT=1024L*1024*1024;
 static final String CONFIG="pulseMs similarity delayMs pressMs swipeMs swipePercent swipeFromCentre fastPerformance hybridSearch alternateSizes confirm repeat useRegions regions detailedLauncher simplePopupSize advancedPopupSize focusGuides touchPulse reduceMotion runMode";
 static String[] groups(){return new String[]{"config","automation","auto-tap"};}
 static boolean allowed(String group,String key){return group.equals("config")?Arrays.asList(CONFIG.split(" ")).contains(key):group.equals("automation")?Arrays.asList("general","timeline","loop").contains(key):key.equals("plan")||key.matches("(slot|name)[0-2]");}
 static JSONObject portable(Context c)throws JSONException{JSONObject root=new JSONObject();for(String g:groups()){JSONObject values=new JSONObject();for(Map.Entry<String,?> e:c.getSharedPreferences(g,0).getAll().entrySet())if(allowed(g,e.getKey())){Object v=e.getValue();JSONObject item=new JSONObject();item.put("type",v instanceof Boolean?"b":v instanceof Integer?"i":v instanceof Long?"l":v instanceof Float?"f":"s");item.put("value",v);values.put(e.getKey(),item);}root.put(g,values);}return root;}
 static void exportAll(Context c,OutputStream out)throws Exception{try(ZipOutputStream zip=new ZipOutputStream(new BufferedOutputStream(out))){JSONObject m=new JSONObject();m.put("format","autobash-global");m.put("version",1);m.put("settings",portable(c));JSONObject active=new JSONObject();for(ActionType a:ActionType.values())active.put(a.id,PresetStore.active(ActionType.scope(c,a)));m.put("active",active);zip.putNextEntry(new ZipEntry("global.json"));zip.write(m.toString().getBytes(StandardCharsets.UTF_8));zip.closeEntry();long total=0;for(ActionType a:ActionType.values())for(int slot=0;slot<3;slot++){File temp=File.createTempFile("global-export",".zip",c.getCacheDir());try{try(OutputStream f=new FileOutputStream(temp)){PresetArchive.exportSlot(ActionType.scope(c,a),slot,f);}total+=temp.length();if(total>LIMIT)throw new IOException("Backup exceeds 1 GiB");zip.putNextEntry(new ZipEntry(a.id+"-"+slot+".zip"));try(InputStream in=new FileInputStream(temp)){copy(in,zip,PresetArchive.MAX_TOTAL);}zip.closeEntry();}finally{temp.delete();}}}}
 static long copy(InputStream in,OutputStream out,long limit)throws IOException{byte[] b=new byte[32768];long n=0;int k;while((k=in.read(b))!=-1){n+=k;if(n>limit)throw new IOException("Backup exceeds size limit");out.write(b,0,k);}return n;}
 static class Staged implements AutoCloseable{final Map<String,PresetArchive.Staged> slots=new LinkedHashMap<>();JSONObject manifest;int count(){int n=0;for(PresetArchive.Staged s:slots.values())n+=s.count();return n;}public void close(){for(PresetArchive.Staged s:slots.values())s.close();}}
 static Staged stage(Context c,InputStream input)throws Exception{if(input==null)throw new IOException("Cannot open backup");Staged s=new Staged();boolean ok=false;Set<String> seen=new HashSet<>();long total=0,expanded=0;try(ZipInputStream z=new ZipInputStream(new BufferedInputStream(input))){ZipEntry e;while((e=z.getNextEntry())!=null){String name=e.getName();if(!seen.add(name)||e.isDirectory())throw new IOException("Repeated or invalid backup entry");if(name.equals("global.json")){ByteArrayOutputStream b=new ByteArrayOutputStream();total+=copy(z,b,4*1024*1024);s.manifest=new JSONObject(b.toString("UTF-8"));}else{if(!name.matches("(tap|left|right|up|down|back|home)-[0-2]\\.zip"))throw new IOException("Unexpected backup entry");File f=File.createTempFile("global-read",".zip",c.getCacheDir());try{try(OutputStream o=new FileOutputStream(f)){total+=copy(z,o,PresetArchive.MAX_TOTAL);}try(InputStream in=new FileInputStream(f)){PresetArchive.Staged p=PresetArchive.stage(c,in);if(!name.startsWith(p.action.id+"-")){p.close();throw new IOException("Wrong action in backup");}s.slots.put(name,p);for(File image:PresetStore.files(p.folder))expanded+=image.length();if(expanded>LIMIT)throw new IOException("Expanded backup exceeds 1 GiB");}}finally{f.delete();}}if(total>LIMIT)throw new IOException("Backup exceeds 1 GiB");}
 if(s.manifest==null||!s.manifest.getString("format").equals("autobash-global")||s.manifest.getInt("version")!=1||s.slots.size()!=21)throw new IOException("Incomplete or unsupported global backup");validate(s.manifest);ok=true;return s;}finally{if(!ok)s.close();}}
 static void validate(JSONObject m)throws Exception{JSONObject settings=m.getJSONObject("settings");for(String g:groups()){JSONObject v=settings.getJSONObject(g);Iterator<String> keys=v.keys();while(keys.hasNext()){String k=keys.next();if(!allowed(g,k))throw new IOException("Unsupported setting");JSONObject item=v.getJSONObject(k);String t=item.getString("type");Object value=item.get("value");String expected=g.equals("auto-tap")?"s":g.equals("automation")?(k.equals("loop")?"b":"s"):(k.equals("regions")||k.equals("runMode")?"s":Arrays.asList("pulseMs","similarity","delayMs","pressMs","swipeMs","swipePercent","simplePopupSize","advancedPopupSize").contains(k)?"i":"b");if(!t.equals(expected))throw new IOException("Wrong setting type");if(t.equals("i")&&(item.getInt("value")<0||item.getInt("value")>60000))throw new IOException("Setting outside range");if(g.equals("config")&&t.equals("i")){int n=item.getInt("value");int min=k.equals("similarity")?75:k.endsWith("PopupSize")?75:k.equals("pulseMs")?100:k.equals("pressMs")?40:k.equals("swipeMs")?150:k.equals("swipePercent")?10:0;int max=k.equals("similarity")?100:k.endsWith("PopupSize")?150:k.equals("pulseMs")?10000:k.equals("pressMs")?250:k.equals("swipeMs")?1000:k.equals("swipePercent")?70:5000;if(n<min||n>max)throw new IOException("Setting outside supported range");}if(g.equals("config")&&k.equals("runMode")&&!Arrays.asList("recognition","general","timeline").contains(item.getString("value")))throw new IOException("Invalid run mode");if(t.equals("b")){if(!(value instanceof Boolean))throw new IOException("Invalid switch");}else if(t.equals("i")){item.getInt("value");}else if(t.equals("s")){if(!(value instanceof String))throw new IOException("Invalid text");}else throw new IOException("Unsupported setting type");if(g.equals("auto-tap")&&(k.equals("plan")||k.startsWith("slot")))AutoTapPlan.decode(item.getString("value"));if(g.equals("automation")&&!k.equals("loop")){JSONArray a=new JSONArray(item.getString("value"));if(a.length()>100)throw new IOException("Too many steps");for(int i=0;i<a.length();i++)TimedAction.parse(a.getJSONObject(i));}}}for(ActionType a:ActionType.values())PresetStore.check(m.getJSONObject("active").getInt(a.id));}
 static void restore(SharedPreferences p,Map<String,?> values){SharedPreferences.Editor e=p.edit().clear();for(Map.Entry<String,?> v:values.entrySet()){Object x=v.getValue();if(x instanceof String)e.putString(v.getKey(),(String)x);else if(x instanceof Boolean)e.putBoolean(v.getKey(),(Boolean)x);else if(x instanceof Integer)e.putInt(v.getKey(),(Integer)x);else if(x instanceof Long)e.putLong(v.getKey(),(Long)x);else if(x instanceof Float)e.putFloat(v.getKey(),(Float)x);}if(!e.commit())throw new IllegalStateException("Could not restore settings");}

 static List<String> preferenceNames(){List<String> n=new ArrayList<>(Arrays.asList("config","automation","auto-tap","target-options"));for(ActionType a:ActionType.values())n.add(a==ActionType.TAP?"presets":"presets-"+a.id);return n;}
 static File journal(Context c){return new File(c.getFilesDir(),"global-restore-journal.json");}
 static void checkpoint(Context c)throws Exception{JSONObject root=new JSONObject();for(String name:preferenceNames()){JSONObject values=new JSONObject();for(Map.Entry<String,?> item:c.getSharedPreferences(name,0).getAll().entrySet()){Object v=item.getValue();JSONObject record=new JSONObject();record.put("type",v instanceof Boolean?"b":v instanceof Integer?"i":v instanceof Long?"l":v instanceof Float?"f":"s");record.put("value",v);values.put(item.getKey(),record);}root.put(name,values);}android.util.AtomicFile atomic=new android.util.AtomicFile(journal(c));FileOutputStream out=atomic.startWrite();try{out.write(root.toString().getBytes(StandardCharsets.UTF_8));atomic.finishWrite(out);}catch(Exception e){atomic.failWrite(out);throw e;}}
 static synchronized void recover(Context c){if(!journal(c).exists())return;try{JSONObject root=new JSONObject(new String(new android.util.AtomicFile(journal(c)).readFully(),StandardCharsets.UTF_8));for(String name:preferenceNames()){JSONObject values=root.getJSONObject(name);Map<String,Object> saved=new HashMap<>();Iterator<String> it=values.keys();while(it.hasNext()){String key=it.next();JSONObject v=values.getJSONObject(key);switch(v.getString("type")){case "b":saved.put(key,v.getBoolean("value"));break;case "i":saved.put(key,v.getInt("value"));break;case "l":saved.put(key,v.getLong("value"));break;case "f":saved.put(key,(float)v.getDouble("value"));break;default:saved.put(key,v.getString("value"));}}restore(c.getSharedPreferences(name,0),saved);}new android.util.AtomicFile(journal(c)).delete();}catch(Exception e){android.util.Log.e("AutoBash","Backup recovery incomplete",e);}c.getSharedPreferences("config",0).edit().putBoolean("tap",false).putBoolean("sessionActive",false).commit();c.getSharedPreferences("auto-tap",0).edit().putBoolean("active",false).commit();}
 static synchronized void install(Context c,Staged s)throws Exception{
  Map<SharedPreferences,Map<String,?>> old=new LinkedHashMap<>();for(String g:groups()){SharedPreferences p=c.getSharedPreferences(g,0);old.put(p,new HashMap<>(p.getAll()));}SharedPreferences opts=c.getSharedPreferences("target-options",0);old.put(opts,new HashMap<>(opts.getAll()));for(ActionType a:ActionType.values()){SharedPreferences p=PresetStore.prefs(ActionType.scope(c,a));old.put(p,new HashMap<>(p.getAll()));}
  checkpoint(c);try{validate(s.manifest);for(ActionType a:ActionType.values()){Context scoped=ActionType.scope(c,a);SharedPreferences.Editor editor=PresetStore.prefs(scoped).edit();for(int slot=0;slot<3;slot++){PresetArchive.Staged p=s.slots.get(a.id+"-"+slot+".zip");if(p==null||p.committed)throw new IOException("Backup is unavailable");for(int i=0;i<p.count();i++)p.options.get(i).save(c,new File(p.folder,PresetArchive.fileName(i)));editor.putString("dir"+slot,p.folder.getName()).putString("name"+slot,p.name);}if(!editor.putInt("active",s.manifest.getJSONObject("active").getInt(a.id)).commit())throw new IOException("Could not save collections");}
   for(String g:groups()){SharedPreferences.Editor e=c.getSharedPreferences(g,0).edit();for(String k:new HashSet<>(c.getSharedPreferences(g,0).getAll().keySet()))if(allowed(g,k))e.remove(k);JSONObject v=s.manifest.getJSONObject("settings").getJSONObject(g);Iterator<String> keys=v.keys();while(keys.hasNext()){String k=keys.next();JSONObject item=v.getJSONObject(k);switch(item.getString("type")){case "b":e.putBoolean(k,item.getBoolean("value"));break;case "i":e.putInt(k,item.getInt("value"));break;case "s":e.putString(k,item.getString("value"));break;}}if(g.equals("config"))e.putBoolean("tap",false).putBoolean("sessionActive",false).remove("sessionCheckpoint");if(g.equals("auto-tap"))e.putBoolean("active",false).putLong("taps",0).putLong("cyclesDone",0).putInt("next",0).putBoolean("pending",false);if(!e.commit())throw new IOException("Could not save settings");}
   new android.util.AtomicFile(journal(c)).delete();for(PresetArchive.Staged p:s.slots.values())p.committed=true;
  }catch(Exception e){for(Map.Entry<SharedPreferences,Map<String,?>> p:old.entrySet())restore(p.getKey(),p.getValue());new android.util.AtomicFile(journal(c)).delete();throw e;}
 }
}
